package com.droiddeck.launcher.migration.archive;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.apache.commons.compress.archivers.tar.*;
public class MigrationArchiveTest {
 private byte[] tar(String... names) throws Exception { ByteArrayOutputStream b=new ByteArrayOutputStream(); try(TarArchiveOutputStream t=new TarArchiveOutputStream(b)){ t.setLongFileMode(TarArchiveOutputStream.LONGFILE_POSIX); for(String n:names){TarArchiveEntry e=new TarArchiveEntry(n);e.setSize(1);t.putArchiveEntry(e);t.write(1);t.closeArchiveEntry();}}return b.toByteArray(); }
 private String[] valid(){return new String[]{"linuxfs/usr/bin/gamescope","linuxfs/usr/local/bin/droiddeck-session","linuxfs/.version"};}
 private byte[] with(String name) throws Exception {String[] n=Arrays.copyOf(valid(),4);n[3]=name;return tar(n);}
 @Test public void inspectRuntime() throws Exception {MigrationArchive.Inspection i=MigrationArchive.inspect(new ByteArrayInputStream(tar(valid())),100,null);assertEquals(3,i.entries);assertEquals(3,i.unpackedBytes);}
 @Test public void rejectTraversal() throws Exception {assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(with("../escape")),100,null));}
 @Test public void rejectDuplicate() throws Exception {assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(with("linuxfs/.version")),100,null));}
 @Test public void rejectBound() throws Exception {assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(tar(valid())),2,null));}
 @Test public void rejectTruncatedTrailer() throws Exception {byte[] bytes=tar(valid());assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(Arrays.copyOf(bytes,3072)),100,null));}
 @Test public void rejectMissingRuntime() throws Exception {assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(tar("hello")),100,null));}
 private byte[] linked(String target, boolean hard, boolean child) throws Exception {ByteArrayOutputStream b=new ByteArrayOutputStream();try(TarArchiveOutputStream t=new TarArchiveOutputStream(b)){t.setLongFileMode(TarArchiveOutputStream.LONGFILE_POSIX);for(String n:valid()){TarArchiveEntry e=new TarArchiveEntry(n);e.setMode(0755);e.setSize(1);t.putArchiveEntry(e);t.write(1);t.closeArchiveEntry();}TarArchiveEntry e=new TarArchiveEntry("linuxfs/link",hard?TarConstants.LF_LINK:TarConstants.LF_SYMLINK);e.setLinkName(target);t.putArchiveEntry(e);t.closeArchiveEntry();if(child){e=new TarArchiveEntry("linuxfs/link/child");e.setSize(1);t.putArchiveEntry(e);t.write(1);t.closeArchiveEntry();}}return b.toByteArray();}
 @Test public void absoluteGuestLinkPreserved() throws Exception {Path p=Files.createTempDirectory("migration");MigrationArchive.extract(new ByteArrayInputStream(linked("/usr/bin",false,false)),p,100,null);assertEquals("/usr/bin",Files.readSymbolicLink(p.resolve("linuxfs/link")).toString());assertTrue(Files.isExecutable(p.resolve(valid()[0])));}
 @Test public void symlinkAncestorRejected() throws Exception {assertThrows(IOException.class,()->MigrationArchive.extract(new ByteArrayInputStream(linked("/tmp",false,true)),Files.createTempDirectory("migration"),100,null));}
 @Test public void hardlinkRestored() throws Exception {Path p=Files.createTempDirectory("migration");MigrationArchive.extract(new ByteArrayInputStream(linked(valid()[0],true,false)),p,100,null);assertEquals(1,Files.size(p.resolve("linuxfs/link")));}
 @Test public void exportExcludesTransientAndCredentials() throws Exception {Path p=Files.createTempDirectory("migration");for(String n:valid()){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}for(String n:new String[]{"linuxfs/tmp/secret","session/state","stores/epic/credentials.json","stores/epic/account_tokens.json"}){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,"{}".getBytes(),null);Set<String> names=new HashSet<>();try(TarArchiveInputStream t=new TarArchiveInputStream(new ByteArrayInputStream(b.toByteArray()))){TarArchiveEntry e;while((e=t.getNextEntry())!=null)names.add(e.getName());}assertFalse(names.contains("linuxfs/tmp/secret"));assertFalse(names.contains("session/state"));assertFalse(names.contains("stores/epic/credentials.json"));assertFalse(names.contains("stores/epic/account_tokens.json"));assertTrue(names.contains("migration-settings.json"));}
 @Test public void directoryCannotServeAsGamescope() throws Exception {String[] n=valid();n[0]+="/";assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(tar(n)),100,null));}
 @Test public void directoryFileConflictRejected() throws Exception {String[] n=Arrays.copyOf(valid(),5);n[3]="extra/";n[4]="extra";assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(tar(n)),100,null));}
 @Test public void truncatedPayloadRejected() throws Exception {byte[] bytes=tar(valid());assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(Arrays.copyOf(bytes,512)),100,null));}
 @Test public void preexistingSymlinkRejected() throws Exception {Path p=Files.createTempDirectory("migration");Path outside=Files.createTempDirectory("outside");Files.createSymbolicLink(p.resolve("linuxfs"),outside);assertThrows(IOException.class,()->MigrationArchive.extract(new ByteArrayInputStream(tar(valid())),p,100,null));assertFalse(Files.exists(outside.resolve("usr")));}
 @Test public void extractionBoundEnforced() throws Exception {assertThrows(IOException.class,()->MigrationArchive.extract(new ByteArrayInputStream(tar(valid())),Files.createTempDirectory("migration"),2,null));}
 @Test public void missingHardlinkTargetRejectedDuringInspection() throws Exception {assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(linked("missing",true,false)),100,null));}
 private byte[] rooted(String rootName, byte kind, boolean emptyVersion) throws Exception {ByteArrayOutputStream b=new ByteArrayOutputStream();try(TarArchiveOutputStream t=new TarArchiveOutputStream(b)){TarArchiveEntry root=new TarArchiveEntry(rootName,kind);root.setMode(0000);t.putArchiveEntry(root);t.closeArchiveEntry();for(String n:valid()){TarArchiveEntry e=new TarArchiveEntry(n);int size=emptyVersion&&n.endsWith(".version")?0:1;e.setSize(size);t.putArchiveEntry(e);if(size>0)t.write(1);t.closeArchiveEntry();}}return b.toByteArray();}
 @Test public void legacyRootDirectoryAcceptedWithoutChangingPermissions() throws Exception {Path p=Files.createTempDirectory("migration");MigrationArchive.Inspection i=MigrationArchive.extract(new ByteArrayInputStream(rooted("./",TarConstants.LF_DIR,false)),p,100,null);assertTrue(Files.isReadable(p));assertTrue(Files.isExecutable(p));assertEquals(3,i.unpackedBytes);}
 @Test public void dotDirectoryAccepted() throws Exception {MigrationArchive.inspect(new ByteArrayInputStream(rooted(".",TarConstants.LF_DIR,false)),100,null);}
 @Test public void rootFileRejected() throws Exception {assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(rooted(".",TarConstants.LF_NORMAL,false)),100,null));}
 @Test public void longPathRejected() throws Exception {String n=String.join("/",Collections.nCopies(42,"x".repeat(100)));assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(with(n)),100,null));}
 @Test public void deepPathRejected() throws Exception {String n=String.join("/",Collections.nCopies(129,"x"));assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(with(n)),100,null));}
 @Test public void emptyVersionRejected() throws Exception {assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(rooted("root/",TarConstants.LF_DIR,true)),100,null));}
 @Test public void exportProgressUpdatesInsideLargeFile() throws Exception {Path p=Files.createTempDirectory("migration");Files.write(p.resolve("big"),new byte[3*1024*1024]);List<Long> updates=new ArrayList<>();MigrationArchive.write(p,new ByteArrayOutputStream(),new byte[0],(bytes,entries)->updates.add(bytes));assertTrue(updates.stream().anyMatch(n->n>0&&n<3*1024*1024));}
 private byte[] rawHeader(String name, byte type, long size) {TarArchiveEntry e=new TarArchiveEntry(name,type);e.setSize(size);byte[] header=new byte[512];e.writeEntryHeader(header);return header;}
 @Test public void oversizedMetadataHeaderRejectedBeforeBodyRead() throws Exception {byte[] header=rawHeader("pax",TarConstants.LF_PAX_EXTENDED_HEADER_LC,33L*1024*1024);InputStream guarded=new InputStream(){int at;public int read(){if(at<header.length)return header[at++]&255;throw new AssertionError("Oversized PAX payload must not be consumed");}};assertThrows(IOException.class,()->MigrationArchive.inspect(guarded,100,null));}
 @Test public void aggregateMetadataBoundEnforced() throws Exception {Enumeration<InputStream> members=new Enumeration<InputStream>(){int index;public boolean hasMoreElements(){return index<8501;}public InputStream nextElement(){if(index++==8500)return new ByteArrayInputStream(new byte[1024]);String n="x".repeat(3990)+"/"+index;byte[] name=n.getBytes(java.nio.charset.StandardCharsets.UTF_8);ByteArrayOutputStream b=new ByteArrayOutputStream();try{b.write(rawHeader("././@LongLink",TarConstants.LF_GNUTYPE_LONGNAME,name.length+1));b.write(name);b.write(new byte[4096-name.length]);b.write(rawHeader("member",TarConstants.LF_NORMAL,0));}catch(IOException impossible){throw new AssertionError(impossible);}return new ByteArrayInputStream(b.toByteArray());}};assertThrows(IOException.class,()->MigrationArchive.inspect(new SequenceInputStream(members),100,null));}
 @Test public void longLinkTargetRejected() throws Exception {assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(linked("/"+"x".repeat(4096),false,false)),100,null));}
 @Test public void importProgressUpdatesInsideLargeFile() throws Exception {Path p=Files.createTempDirectory("migration");for(String n:valid()){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}Files.write(p.resolve("big"),new byte[3*1024*1024]);ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,new byte[0],null);List<Long> updates=new ArrayList<>();MigrationArchive.inspect(new ByteArrayInputStream(b.toByteArray()),4*1024*1024,(bytes,entries)->updates.add(bytes));assertTrue(updates.stream().anyMatch(n->n>0&&n<3*1024*1024));}
 private Path runtimeTree() throws Exception {Path p=Files.createTempDirectory("migration");for(String n:valid()){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}return p;}
 @Test public void oversizedVersionRejectedByInspectAndExtract() throws Exception {Path p=runtimeTree();Files.write(p.resolve("linuxfs/.version"),new byte[65]);ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,new byte[0],null);byte[] bytes=b.toByteArray();assertThrows(IOException.class,()->MigrationArchive.inspect(new ByteArrayInputStream(bytes),1000,null));assertThrows(IOException.class,()->MigrationArchive.extract(new ByteArrayInputStream(bytes),Files.createTempDirectory("migration"),1000,null));}
 @Test public void roundTripPreservesOwnerAndGroupPermissions() throws Exception {Path p=runtimeTree();Path normal=p.resolve("private-data");Files.write(normal,new byte[]{1});Files.setPosixFilePermissions(normal,java.nio.file.attribute.PosixFilePermissions.fromString("rw-r-----"));Path exec=p.resolve(valid()[0]);Files.setPosixFilePermissions(exec,java.nio.file.attribute.PosixFilePermissions.fromString("rwxr-x---"));ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,new byte[0],null);Path dest=Files.createTempDirectory("migration");MigrationArchive.extract(new ByteArrayInputStream(b.toByteArray()),dest,1000,null);assertEquals(Files.getPosixFilePermissions(normal),Files.getPosixFilePermissions(dest.resolve("private-data")));assertEquals(Files.getPosixFilePermissions(exec),Files.getPosixFilePermissions(dest.resolve(valid()[0])));}
 @Test public void roundTripPreservesHardlinkAndWritesPayloadOnce() throws Exception {Path p=runtimeTree();Files.write(p.resolve("linked-original"),new byte[]{1,2,3});Files.createLink(p.resolve("linked-alias"),p.resolve("linked-original"));ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,new byte[0],null);int links=0;try(TarArchiveInputStream t=new TarArchiveInputStream(new ByteArrayInputStream(b.toByteArray()))){TarArchiveEntry e;while((e=t.getNextEntry())!=null)if(e.isLink())links++;}assertEquals(1,links);Path dest=Files.createTempDirectory("migration");MigrationArchive.Inspection result=MigrationArchive.extract(new ByteArrayInputStream(b.toByteArray()),dest,1000,null);assertEquals(6,result.unpackedBytes);assertTrue(Files.isSameFile(dest.resolve("linked-original"),dest.resolve("linked-alias")));}
 @Test public void audioAndInstallTransientStateExcluded() throws Exception {Path p=runtimeTree();String[] paths={"directaudio/relay-state","pulseaudio/default.pa",".proton-install-rt/state","gpu-clock-pinned"};for(String n:paths){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,new byte[0],null);Set<String> names=new HashSet<>();try(TarArchiveInputStream t=new TarArchiveInputStream(new ByteArrayInputStream(b.toByteArray()))){TarArchiveEntry e;while((e=t.getNextEntry())!=null)names.add(e.getName());}for(String n:paths)assertFalse(n,names.contains(n));}
 private String steamRoot(){return "linuxfs/root/.local/share/Steam/";}
 @Test public void personalBackupOmitsLoginAndBrowserIdentity() throws Exception {Path p=runtimeTree();String[] privateFiles={steamRoot()+"config/htmlcache/Login Data",steamRoot()+"config/loginusers.vdf",steamRoot()+"logs/bootstrap_log.txt",steamRoot()+"ssfn123", "linuxfs/etc/machine-id","linuxfs/var/lib/dbus/machine-id","linuxfs/var/log/system.log","linuxfs/root/.cache/browser/History","linuxfs/root/.steam/private-token"};for(String n:privateFiles){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,new byte[0],null);Set<String> names=tarNames(b.toByteArray());for(String n:privateFiles)assertFalse(n,names.contains(n));}
 private Set<String> tarNames(byte[] bytes)throws Exception {Set<String> names=new HashSet<>();try(TarArchiveInputStream t=new TarArchiveInputStream(new ByteArrayInputStream(bytes))){TarArchiveEntry e;while((e=t.getNextEntry())!=null)names.add(e.getName());}return names;}
 @Test public void runtimeSharingWhitelistRetainsSoftwareAndDropsPersonalFiles() throws Exception {Path p=runtimeTree();String[] privateFiles={steamRoot()+"userdata/123/save.dat",steamRoot()+"steamapps/compatdata/123/pfx/user.reg",steamRoot()+"steamapps/shadercache/123/cache",steamRoot()+"steamapps/common/PersonalGame/save.dat",steamRoot()+"opaque-personal.txt","linuxfs/root/Documents/private.txt","stores/game/library.json","personal.json","linuxfs/home/player/private.txt"};String[] software={steamRoot()+"ubuntu12_32/steam",steamRoot()+"package/steam_client_linux",steamRoot()+"compatibilitytools.d/GE-Proton/proton",steamRoot()+"steamapps/common/Proton 9.0/proton","graphics_driver/libvulkan.so","components/proton.tar"};for(String n:privateFiles){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}for(String n:software){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}Files.createDirectories(p.resolve("linuxfs/root/.steam"));Files.createSymbolicLink(p.resolve("linuxfs/root/.steam/steam"),Paths.get("../.local/share/Steam"));ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,new byte[0],null,true);Set<String> names=tarNames(b.toByteArray());for(String n:privateFiles)assertFalse(n,names.contains(n));for(String n:software)assertTrue(n,names.contains(n));assertTrue(names.contains("linuxfs/root/.steam/steam"));Path dest=Files.createTempDirectory("migration");MigrationArchive.extract(new ByteArrayInputStream(b.toByteArray()),dest,1000,null);assertTrue(Files.exists(dest.resolve(valid()[0])));}
 @Test public void runtimeSharingKeepsArmClientUiAndProtonInstallMarkers() throws Exception {Path p=runtimeTree();String[] required={steamRoot()+"steamrtarm64/steam",steamRoot()+"steamrt32/runtime",steamRoot()+"steamrt64/runtime",steamRoot()+"linuxarm64/steam",steamRoot()+"androidarm64/steam",steamRoot()+"steamui/index.html",steamRoot()+"steam/client",steamRoot()+"tenfoot/ui",steamRoot()+"controller_base/steamcontroller.vdf",steamRoot()+"graphics/icon.png",steamRoot()+"legacycompat/runtime",steamRoot()+"steamapps/appmanifest_4427310.acf","linuxfs/.droiddeck-pkg-proton-arm64"};for(String n:required){Files.createDirectories(p.resolve(n).getParent());Files.write(p.resolve(n),new byte[]{1});}Files.createSymbolicLink(p.resolve(steamRoot()+"steamrtarm32"),Paths.get("steamrt32"));ByteArrayOutputStream b=new ByteArrayOutputStream();MigrationArchive.write(p,b,new byte[0],null,true);Set<String> names=tarNames(b.toByteArray());for(String n:required)assertTrue(n,names.contains(n));assertTrue(names.contains(steamRoot()+"steamrtarm32"));}
 @Test public void runtimeSharingExcludesLinuxPasswordHashesAndPrivateKeys() {String[] secret={"linuxfs/etc/shadow","linuxfs/etc/shadow-","linuxfs/etc/gshadow","linuxfs/etc/gshadow-","linuxfs/etc/ssl/private/key.pem","linuxfs/etc/ssh/ssh_host_ed25519_key","linuxfs/etc/ssh/ssh_host_ed25519_key.pub","linuxfs/etc/pacman.d/gnupg/private-keys-v1.d/key"};for(String n:secret){assertFalse(n,MigrationArchive.shouldExport(n,false,false,true));assertTrue(n,MigrationArchive.shouldExport(n,false,false,false));}assertFalse(MigrationArchive.shouldExport("linuxfs/etc/ssl/private",true,false,true));assertFalse(MigrationArchive.shouldExport("linuxfs/etc/pacman.d/gnupg/private-keys-v1.d",true,false,true));assertTrue(MigrationArchive.shouldExport("linuxfs/etc/ssh/sshd_config",false,false,true));}
}
